/* Finds the games: every src/games/<id>/disk.ts is a disk in the box, sorted by `order`.
   The game code (game.ts) is only fetched when its disk is loaded. */
import type { GameDisk, CreateGame, Cover, Preview } from './types';

const diskModules = import.meta.glob<{ disk: GameDisk }>('./*/disk.ts', { eager: true });
const gameModules = import.meta.glob<{ default: CreateGame }>('./*/game.ts');
// the launcher's art, generated by tools/share-images/make.cjs and attached to the disk in the same folder
const coverModules = import.meta.glob<{ cover: Cover }>('./*/cover.ts', { eager: true });
// previews are bigger (8 frames each), so they're fetched while the launcher is up, not in the main bundle
const previewModules = import.meta.glob<{ preview: Preview }>('./*/preview.ts');

for (const [path, m] of Object.entries(diskModules)) m.disk.cover = coverModules[`./${path.split('/')[1]}/cover.ts`]?.cover;

/** Fetch every disk's flipbook preview and attach it to its disk as `preview`. Once they all arrive this is a no-op;
    if any failed (offline and not cached), the next call (the next visit to the menu) tries those again. */
let previewsAsked: Promise<void> | null = null;
export function loadPreviews(): Promise<void> {
  return (previewsAsked ??= Promise.all(Object.entries(diskModules).map(async ([path, m]) => {
    const load = previewModules[`./${path.split('/')[1]}/preview.ts`];
    if (!load || m.disk.preview) return true;
    try { m.disk.preview = (await load()).preview; return true; } catch (_) { return false; /* the cover stays still for now */ }
  })).then(ok => { if (ok.includes(false)) previewsAsked = null; }));
}

export const DISKS: GameDisk[] = Object.values(diskModules).map(m => m.disk).sort((a, b) => a.order - b.order);

/* ---------- disks added while the console runs (GAM-64: games an AI harness makes, sent in through the embed bridge) ---------- */
const BUILT_IN = new Set(DISKS.map(d => d.id));
const added = new Map<string, () => Promise<CreateGame>>();

/** Put a disk in the box at run time, or replace one added earlier with the same id. Its game code is fetched
    by `load` when the disk is loaded, like a built-in game's. Built-in disks can't be replaced. */
export function addDisk(disk: GameDisk, load: () => Promise<CreateGame>): void {
  if (BUILT_IN.has(disk.id)) throw new Error(`"${disk.id}" is a built-in disk`);
  const i = DISKS.findIndex(d => d.id === disk.id);
  if (i >= 0) DISKS.splice(i, 1);
  DISKS.push(disk);
  DISKS.sort((a, b) => a.order - b.order);
  added.set(disk.id, load);
}
/** Whether a disk was added at run time (see addDisk). */
export const isAdded = (id: string) => added.has(id);

/** Fetch a game's code (once; later calls reuse the module). */
export async function loadGameCode(id: string): Promise<CreateGame> {
  const load = added.get(id);
  if (load) return load();
  const entry = Object.entries(gameModules).find(([path]) => path === `./${dirOf(id)}/game.ts`);
  if (!entry) throw new Error(`No game.ts for disk "${id}"`);
  return (await entry[1]()).default;
}

/* a disk's folder: the one whose disk.ts declared this id */
function dirOf(id: string){
  const hit = Object.entries(diskModules).find(([, m]) => m.disk.id === id);
  if (!hit) throw new Error(`Unknown disk "${id}"`);
  return hit[0].split('/')[1];
}
